{% block title %}Problem Detail{% endblock %}

{% block content %}
<div class="container mt-4">
    <h1 class="text-center">{{ problem.title }}</h1>
    <hr>
    <div class="problem-details">
        <h4>Description</h4>
        <p>{{ problem.description }}</p>

        <h4>Input Format</h4>
        <p>{{ problem.input_format }}</p>

