        <h4>Solutions</h4>
        {% if solutions %}
            <ul class="list-group">
                {% for solution in solutions %}
                    <li class="list-group-item">
                        <strong>User:</strong> {{ solution.user.username }} <br>
                        <strong>Submission Date:</strong> {{ solution.submitted_at.strftime('%Y-%m-%d %H:%M:%S') }} <br>
                        <strong>Status:</strong> {{ solution.status }}
